<!doctype html>
<html lang="hy">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>DRIVE — Ավտոսրահ</title>
<style>
:root{--bg:#0b0f14;--panel:#121922;--panel2:#18222d;--text:#f4f7fb;--muted:#9ba8b7;--accent:#c7f36b;--line:#273442}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Arial,sans-serif}.wrap{max-width:1240px;margin:auto;padding:0 22px}.top{display:flex;align-items:center;justify-content:space-between;padding:22px 0;border-bottom:1px solid var(--line)}.logo{font-size:25px;font-weight:900;letter-spacing:3px}.logo span{color:var(--accent)}.top small{color:var(--muted)}.hero{padding:52px 0 34px;display:grid;grid-template-columns:1.2fr .8fr;gap:25px;align-items:center}.eyebrow{color:var(--accent);font-size:12px;font-weight:800;letter-spacing:2px}h1{font-size:clamp(34px,5vw,62px);line-height:1.02;margin:12px 0 16px;letter-spacing:-2px}.hero p{color:var(--muted);line-height:1.7;max-width:600px}.hero-box{background:linear-gradient(135deg,#1b2a37,#10161d);border:1px solid var(--line);border-radius:22px;padding:25px;min-height:190px;display:flex;flex-direction:column;justify-content:space-between}.hero-box strong{font-size:28px}.hero-box span{color:var(--muted);line-height:1.5}.layout{display:grid;grid-template-columns:270px 1fr;gap:24px;padding-bottom:60px}.sidebar,.formbox{background:var(--panel);border:1px solid var(--line);border-radius:17px;padding:20px;height:max-content}h2{font-size:20px;margin:0 0 16px}label{display:block;font-size:13px;color:var(--muted);margin:13px 0 7px}input,select,textarea{width:100%;padding:11px 12px;border-radius:9px;border:1px solid var(--line);background:#0c1218;color:var(--text);font:inherit;outline:none}input:focus,select:focus,textarea:focus{border-color:var(--accent)}button{border:0;border-radius:10px;padding:12px 15px;font-weight:800;cursor:pointer}.primary{background:var(--accent);color:#10150a;width:100%;margin-top:14px}.secondary{background:var(--panel2);color:var(--text);border:1px solid var(--line)}.addsection{margin:0 0 24px}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 13px}.full{grid-column:1/-1}.notice,.statusline{color:var(--muted);font-size:12px;line-height:1.5;margin-top:12px}.contenthead{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:0 0 15px}.contenthead p{color:var(--muted);font-size:13px;margin:4px 0}.cars{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:17px}.car{overflow:hidden;background:var(--panel);border:1px solid var(--line);border-radius:16px}.photo{height:190px;background:#1b2732;position:relative}.photo img{width:100%;height:100%;object-fit:cover;display:block}.badge{position:absolute;top:12px;left:12px;padding:7px 10px;border-radius:30px;background:#c7f36b;color:#18210b;font-size:11px;font-weight:900}.badge.reserved{background:#ffd36b}.badge.sold{background:#ff8888;color:#310b0b}.carbody{padding:17px}.carbody h3{font-size:21px;margin:0 0 8px}.meta{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0;color:var(--muted);font-size:12px}.meta span{background:var(--panel2);padding:6px 8px;border-radius:6px}.price{font-size:24px;font-weight:900;color:var(--accent);margin:13px 0}.desc{font-size:13px;color:var(--muted);line-height:1.5;min-height:38px}.carfoot{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:15px}.delete{background:transparent;border:1px solid #6b3338;color:#ff9b9b;padding:9px 11px}.empty{color:var(--muted);padding:30px;text-align:center;background:var(--panel);border:1px dashed var(--line);border-radius:15px;grid-column:1/-1}footer{border-top:1px solid var(--line);padding:25px 0;color:var(--muted);font-size:12px}@media(max-width:850px){.hero{grid-template-columns:1fr}.layout{grid-template-columns:1fr}.cars{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.wrap{padding:0 14px}.cars,.formgrid{grid-template-columns:1fr}.full{grid-column:auto}.photo{height:210px}.top small{display:none}}
</style></head><body><div class="wrap">
<header class="top"><div class="logo">DRIVE<span>.</span></div><small>Ավտոմեքենաների առցանց կատալոգ</small></header>
<section class="hero"><div><div class="eyebrow">ԸՆՏՐԻՐ ՔՈ ՀԱՋՈՐԴ ՄԵՔԵՆԱՆ</div><h1>Քո ճանապարհը<br>սկսվում է այստեղ։</h1><p>Ավտոմեքենաների կատալոգ՝ որոնմամբ, ֆիլտրերով, կարգավիճակներով և MySQL տվյալների բազայի կապով։</p></div><div class="hero-box"><div class="eyebrow">DRIVE / CATALOG</div><strong>Գտիր քո ոճը։</strong><span>Սեդաններ, ամենագնացներ և էլեկտրական մեքենաներ՝ մեկ վայրում։</span></div></section>
<section class="addsection formbox"><h2>＋ Ավելացնել մեքենա</h2><form id="carForm"><div class="formgrid">
<div><label for="brand">Մակնիշ</label><input id="brand" required maxlength="80" placeholder="Օր.՝ Toyota"></div><div><label for="model">Մոդել</label><input id="model" required maxlength="100" placeholder="Օր.՝ Camry"></div>
<div><label for="year">Տարեթիվ</label><input id="year" type="number" min="1950" max="2027" required placeholder="2022"></div><div><label for="price">Գին (USD)</label><input id="price" type="number" min="0" step="0.01" required placeholder="25000"></div>
<div><label for="mileage">Վազք (կմ)</label><input id="mileage" type="number" min="0" required value="0"></div><div><label for="fuel">Վառելիք</label><select id="fuel"><option>Բենզին</option><option>Դիզել</option><option>Հիբրիդ</option><option>Էլեկտրական</option><option>Գազ</option></select></div>
<div><label for="transmission">Փոխանցման տուփ</label><select id="transmission"><option>Ավտոմատ</option><option>Մեխանիկական</option><option>Վարիատոր</option></select></div><div><label for="status">Կարգավիճակ</label><select id="status"><option>Առկա է</option><option>Ամրագրված է</option><option>Վաճառված է</option></select></div>
<div class="full"><label for="image_url">Նկարի հղում (ըստ ցանկության)</label><input id="image_url" type="url" maxlength="500" placeholder="https://..."></div><div class="full"><label for="description">Նկարագրություն</label><textarea id="description" rows="2" maxlength="2000" placeholder="Մեքենայի մասին կարճ տեղեկություն"></textarea></div></div><button class="primary" type="submit">Ավելացնել մեքենան</button><div class="notice">Տվյալները կպահպանվեն MySQL-ում՝ PHP-ի միջոցով։</div><div id="formMessage" class="statusline" aria-live="polite"></div></form></section>
<main class="layout"><aside class="sidebar"><h2>Ֆիլտրեր</h2><label for="search">Որոնում</label><input id="search" placeholder="Մակնիշ կամ մոդել"><label for="filterFuel">Վառելիք</label><select id="filterFuel"><option value="">Բոլորը</option><option>Բենզին</option><option>Դիզել</option><option>Հիբրիդ</option><option>Էլեկտրական</option><option>Գազ</option></select><label for="filterStatus">Կարգավիճակ</label><select id="filterStatus"><option value="">Բոլորը</option><option>Առկա է</option><option>Ամրագրված է</option><option>Վաճառված է</option></select><label for="maxPrice">Առավելագույն գին (USD)</label><input id="maxPrice" type="number" min="0" placeholder="Օր.՝ 30000"><label for="sort">Դասավորել ըստ գնի</label><select id="sort"><option value="new">Նոր ավելացված</option><option value="low">Էժանից թանկ</option><option value="high">Թանկից էժան</option></select><button class="secondary" id="reset" type="button" style="width:100%;margin-top:14px">Մաքրել ֆիլտրերը</button></aside>
<section><div class="contenthead"><div><h2 style="margin-bottom:3px">Մեքենաների կատալոգ</h2><p id="count">Բեռնվում է...</p></div><button class="secondary" id="refresh" type="button">Թարմացնել ↻</button></div><div id="cars" class="cars"><div class="empty">Մեքենաները բեռնվում են...</div></div></section></main>
<footer>DRIVE. — Ուսումնական նախագիծ · PHP + MySQL · Գները ցուցադրված են ԱՄՆ դոլարով։</footer></div>
<script>
let allCars=[];const $=id=>document.getElementById(id);const money=n=>'$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
async function api(url,options={}){const r=await fetch(url,options);let d;try{d=await r.json()}catch{throw new Error('Սերվերը սխալ պատասխան է վերադարձրել։')}if(!r.ok)throw new Error(d.message||d.error||'Գործողությունը չհաջողվեց։');return d}
async function loadCars(){ $('cars').innerHTML='<div class="empty">Բեռնվում է...</div>';try{const d=await api('api.php?action=list');allCars=d.cars||[];renderCars()}catch(e){$('cars').innerHTML='<div class="empty">Չհաջողվեց բեռնել մեքենաները։ Ստուգիր Apache/MySQL-ը և տվյալների բազան։</div>';$('count').textContent=e.message}}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderCars(){const q=$('search').value.trim().toLowerCase(),fuel=$('filterFuel').value,status=$('filterStatus').value,max=$('maxPrice').value===''?Infinity:Number($('maxPrice').value);let cars=allCars.filter(c=>(`${c.brand} ${c.model}`).toLowerCase().includes(q)&&(!fuel||c.fuel===fuel)&&(!status||c.status===status)&&Number(c.price)<=max);if($('sort').value==='low')cars.sort((a,b)=>Number(a.price)-Number(b.price));if($('sort').value==='high')cars.sort((a,b)=>Number(b.price)-Number(a.price));$('count').textContent=`Ցուցադրված է ${cars.length} մեքենա`;if(!cars.length){$('cars').innerHTML='<div class="empty">Համապատասխան մեքենա չի գտնվել։</div>';return} $('cars').innerHTML=cars.map(c=>{const cls=c.status==='Վաճառված է'?'sold':c.status==='Ամրագրված է'?'reserved':'';const img=/^https?:\/\//i.test(c.image_url||'')?`<img src="${esc(c.image_url)}" alt="${esc(c.brand+' '+c.model)}" loading="lazy" onerror="this.style.display='none'">`:'';return `<article class="car"><div class="photo">${img}<span class="badge ${cls}">${esc(c.status)}</span></div><div class="carbody"><h3>${esc(c.brand)} ${esc(c.model)}</h3><div class="meta"><span>${esc(c.year)} թ.</span><span>${Number(c.mileage).toLocaleString('en-US')} կմ</span><span>${esc(c.fuel)}</span><span>${esc(c.transmission)}</span></div><div class="price">${money(c.price)}</div><div class="desc">${esc(c.description||'Մանրամասների համար կապ հաստատեք մեզ հետ։')}</div><div class="carfoot"><small style="color:var(--muted)">ID: ${Number(c.id)}</small><button class="delete" data-delete="${Number(c.id)}" type="button">Ջնջել</button></div></div></article>`}).join('')}
$('carForm').addEventListener('submit',async e=>{e.preventDefault();const p={brand:$('brand').value.trim(),model:$('model').value.trim(),year:Number($('year').value),price:Number($('price').value),mileage:Number($('mileage').value),fuel:$('fuel').value,transmission:$('transmission').value,status:$('status').value,image_url:$('image_url').value.trim(),description:$('description').value.trim()};$('formMessage').textContent='Պահպանվում է...';try{const r=await api('api.php?action=add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});$('formMessage').textContent=r.message;$('carForm').reset();$('mileage').value='0';await loadCars()}catch(err){$('formMessage').textContent=err.message}});
$('cars').addEventListener('click',async e=>{const b=e.target.closest('[data-delete]');if(!b)return;const id=Number(b.dataset.delete);if(!confirm(`Ջնջե՞լ մեքենան #${id}։`))return;try{await api('api.php?action=delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});await loadCars()}catch(err){alert(err.message)}});
['search','filterFuel','filterStatus','maxPrice','sort'].forEach(id=>$(id).addEventListener(id==='search'||id==='maxPrice'?'input':'change',renderCars));$('reset').addEventListener('click',()=>{$('search').value='';$('filterFuel').value='';$('filterStatus').value='';$('maxPrice').value='';$('sort').value='new';renderCars()});$('refresh').addEventListener('click',loadCars);loadCars();
</script></body></html>
